# O(1) Constant Time vs O(n) Linear Time
def get_first_element(items):
    return items[0] if items else None  # O(1) time complexity

def linear_search(items, target):
    for item in items:                  # O(n) time complexity
        if item == target:
            return True
    return False

print(get_first_element([10, 20, 30]))
print(linear_search([10, 20, 30], 20))

def example_dominant_terms(nums):
    n = len(nums)
    # Phase 1: O(n)
    total = sum(nums)
    # Phase 2: O(n^2) dominates Phase 1
    pairs = []
    for i in range(n):
        for j in range(n):
            pairs.append((nums[i], nums[j]))
    return total, len(pairs)

print(example_dominant_terms([1, 2, 3]))
